INSERT INTO `tblMedication2` (`idMedication2`, `fkConId`, `isMedicated`, `matin`, `midi`, `soir`, `nuit`, `habitudes`) VALUES
(1, 1100158231, 1, 0, 0, 0, 0, ''),
(2, 2146193178, 0, 0, 0, 0, 0, ''),
(3, 2548, 1, 1, 0, 1, 1, 'Vu qu\'elle peut faire des crises d\'épilepsie, il est important de garder la régularité dans la prise des médicaments. \r\nLe matin vers 8h00 pour lui donner les médicaments dans le lit, il faut les mettre sur une cuillère avec de la compote.  '),
(4, 2146192715, 1, 1, 0, 1, 0, 'Vérifier qu\'elle prenne correctement sa médication'),
(5, 2146189541, 1, 1, 1, 1, 1, ''),
(6, 2146190277, 1, 1, 0, 0, 1, 'Donner avec un verre d\'eau. \r\nSi agité lors des trajets ne pas hésiter à donner 1/4 de reserve '),
(7, 1306411305, 1, 1, 1, 1, 0, 'Prend avec de l\'eau '),
(8, 1228923808, 1, 0, 0, 0, 0, ''),
(9, 2146189783, 1, 1, 0, 1, 0, ''),
(10, 2146192929, 1, 1, 0, 0, 1, ''),
(11, 2146189179, 1, 1, 1, 1, 0, ''),
(12, 2611, 1, 1, 0, 1, 0, 'Ecraser les médicaments et donner avec les premières cuillères du repas '),
(13, 302, 1, 0, 0, 0, 0, 'Donner avec la première cuillère du repas '),
(14, 1195664924, 1, 0, 0, 0, 0, ''),
(15, 2642, 1, 0, 0, 0, 0, ''),
(16, -22390883, 1, 1, 0, 1, 0, 'Il prend ses médicaments lors du repas. A mettre sur une cuillère.'),
(17, 2146193060, 1, 1, 1, 1, 1, 'Emmanuelle se réveille au foyer vers 9h15. Elle prend ses médicaments à cette heure-là avec un verre d\'eau.\r\nElle prend aussi un médicament pour s\'endormir le soir.'),
(18, 2146193061, 1, 1, 0, 1, 0, 'Elle prend ses médicaments avec de l\'eau. A contrôler sa prise.'),
(19, 1191915897, 1, 0, 0, 0, 0, 'Andreï n\'a pas de médicament. Mais, il prend le matin des pruneaux. Il a en réserve des suppositoires selon informations des parents. A consulter son carnet de santé.'),
(20, 1138806721, 1, 0, 0, 0, 0, 'Se référer à la fiche de traitement. \r\nDonner avec un petit café ou un yaout les médicaments solides et pour les médicaments liquides dans un petit verre (lui dire que c\'est du schnaps, c\'est une blague qui le fait beaucoup rire)\r\n'),
(21, 2146189323, 1, 1, 1, 1, 0, 'Donner avec les première cuillères du repas ou un petit suisse '),
(22, 2146189701, 1, 0, 0, 0, 0, 'Attention traitement hors repas. \r\nPrend les traitement avec la boisson '),
(23, 2146190531, 1, 0, 0, 0, 0, ''),
(24, 292, 1, 0, 0, 0, 0, ''),
(25, 674040117, 1, 1, 1, 1, 1, 'Prend seul avec de l\'eau '),
(26, 1191311576, 1, 1, 0, 1, 0, 'Par PEG \r\nA une réserve de Midazolam \r\n '),
(27, 2146190042, 1, 0, 0, 0, 0, ''),
(28, 297, 1, 1, 0, 1, 0, 'Steeve prend ses médicaments avec un verre d\'eau ou un yogourt.\r\nSteeve peut aussi avoir des chutes de tension qui peuvent lui provoquer des malaises.'),
(29, 2146193472, 1, 0, 0, 0, 0, ''),
(30, 982284145, 1, 0, 0, 0, 0, 'Suivre le plan de traitement.'),
(31, 2655, 1, 0, 0, 0, 0, ''),
(32, 1228928441, 1, 0, 0, 0, 0, ''),
(33, -486550603, 1, 1, 1, 1, 1, 'Elle prend ses médicaments avec un verre d\'eau.'),
(34, 2146192710, 1, 1, 0, 1, 0, ''),
(35, 1035988716, 1, 1, 0, 1, 0, 'Il prend ses médicaments avant le repas avec un verre d\'eau. '),
(36, 2604, 1, 1, 1, 1, 1, 'Avant les repas mélanger les médicaments avec de la confiture, un yaourt  ou bien lui donner dans une cuillère avec de l\'eau ou il boit à la paille. Si Ludovic gesticule avec des petits cris c’est qu’il a une gélule collée au palais. Il faut l\'enlever ave'),
(37, 1730687754, 1, 1, 0, 0, 0, 'Il prend une cuillère à café de Métamucil le matin de manière autonome.'),
(38, 1349252291, 1, 1, 1, 1, 0, 'Julien prend ses médicaments avant les repas avec un verre d\'eau.'),
(39, 2215, 1, 1, 1, 1, 1, 'Elle prend ses médicaments avec un verre d\'eau.'),
(40, 2146189370, 0, 0, 0, 0, 0, ''),
(41, 2146192217, 1, 0, 0, 0, 0, 'Se référer au plan de traitement.'),
