(28264, '2024-11-20', '00:00:00', '23:00:00', '28 jours à 80% \r\ndoit faire 67.2 heures du 21.10 au 20.11 donc 67.2 / 31 jours = 2.167 par jour\r\n2.167 * 28 jours = 60.696 heures\r\n80% de 60.696 = 48.56 heures (à 80%) ', 18, 0, 2146190079, 1, 17, 23, NULL, NULL, NULL),
(28265, '2024-11-20', '00:00:00', '06:30:00', '3 jours à 100% \r\ndoit faire 67.2 heures du 21.10 au 20.11 donc 67.2 / 31 jours = 2.167 par jour\r\n2.167 * 3 jours à 100% = 6,5 heures', 18, 0, 2146190079, 1, 17, 6.5, NULL, NULL, NULL),
